{"cards": [{"node_code": "N_5222ba6636ffb41b", "definition": "研究船舶在流体介质中运动时的受力、阻力、推进效率及流体绕流特性的基础理论，涵盖粘性流、非定常流及空化现象。", "boundary": "本节点聚焦于流体与船体相互作用的动力学过程。边界在于区分“流体运动”与“静力平衡”（后者归入船舶静力学）、“结构响应”（后者归入船舶结构力学）。若内容涉及具体螺旋桨设计或导管推进器选型，归入船舶设计或动力装置；若涉及纯数学流体力学方程推导，归入本节点。", "includes": ["船舶阻力（摩擦、兴波、形状阻力）理论", "螺旋桨-船体相互作用及推进效率分析", "空化、空泡及非定常流体效应研究"], "excludes": ["船舶在静止水面上的浮态与稳性计算", "船体结构在流体压力下的强度与稳定性分析"], "sibling_distinctions": [{"other_code": "N_393badbfaae48228", "rule": "流体力学关注流体运动引起的力（如阻力、升力），静力学关注重力与浮力平衡下的姿态（如吃水、稳性）。"}, {"other_code": "N_b1b50983e47ad1a4", "rule": "流体力学侧重流体本身的运动规律及作用力，动力学侧重船舶整体在力作用下的运动状态变化（如操纵、耐波）。"}], "cross_boundary_rule": "若内容涉及“计算流体力学（CFD）求解船舶阻力”，主挂载本节点；若侧重基于阻力结果进行船型线型优化，可关联船舶设计。"}, {"node_code": "N_393badbfaae48228", "definition": "研究船舶在静止流体中处于平衡状态时的浮力、重心、稳性及吃水分布等物理规律，是船舶安全与适航性的基础。", "boundary": "本节点聚焦于“静止”或“准静态”条件下的力平衡。边界在于区分“静力平衡”与“流体动力”（后者归入船舶流体力学）、“结构强度”（后者归入船舶结构力学）。若内容涉及船舶在波浪中的动态响应，归入船舶动力学；若涉及具体舱室布置对重心的影响计算，归入本节点。", "includes": ["浮心、重心、稳心及其相互关系理论", "初稳性、大倾角稳性及复原力矩计算", "船舶吃水、排水量及装载平衡原理"], "excludes": ["船舶在波浪或风浪作用下的动态运动分析", "船体结构在静水压力下的应力与变形分析"], "sibling_distinctions": [{"other_code": "N_5222ba6636ffb41b", "rule": "静力学研究重力与浮力的平衡（静止状态），流体力学研究流体运动产生的阻力与推力（运动状态）。"}, {"other_code": "N_b1b50983e47ad1a4", "rule": "静力学关注平衡位置与姿态，动力学关注偏离平衡后的运动轨迹、加速度及操纵响应。"}], "cross_boundary_rule": "若内容涉及“船舶稳性计算”，主挂载本节点；若涉及“波浪中船舶的横摇运动”，主挂载船舶动力学。"}, {"node_code": "N_b1b50983e47ad1a4", "definition": "研究船舶在波浪、风、流及操纵力作用下运动规律、操纵特性、耐波性及运动控制的基础理论。", "boundary": "本节点聚焦于船舶作为刚体或弹性体在外部激励下的“运动”过程。边界在于区分“整体运动”与“局部流体作用”（后者归入流体力学）、“结构响应”（后者归入结构力学）。若内容涉及具体舵机设计或推进器选型，归入船舶设计；若涉及船舶在波浪中的结构疲劳，归入船舶结构力学。", "includes": ["船舶操纵性（回转、航向保持）理论", "船舶耐波性（横摇、纵摇、垂荡）及运动响应分析", "船舶运动控制与稳定性理论"], "excludes": ["船舶在静止水面上的浮态与稳性计算", "船体结构在波浪载荷下的强度与稳定性分析"], "sibling_distinctions": [{"other_code": "N_5222ba6636ffb41b", "rule": "动力学侧重船舶整体的运动状态（位置、速度、加速度），流体力学侧重产生这些运动状态的流体力机制。"}, {"other_code": "N_393badbfaae48228", "rule": "动力学研究非平衡状态下的运动过程，静力学研究平衡状态下的姿态与力矩平衡。"}], "cross_boundary_rule": "若内容涉及“船舶在波浪中的运动方程求解”，主挂载本节点；若涉及“波浪对船体结构的冲击载荷”，主挂载船舶结构力学。"}]}
